import { cache } from "react";

import { getBtcEtfFlowsData } from "@/lib/dashboard/adapters/btc-etf-flows";
import { getGldFlowPressure } from "@/lib/dashboard/adapters/gld-flow-pressure";
import { getRadarRows } from "@/lib/dashboard/adapters/radar";
import { getSectorEtfsData } from "@/lib/dashboard/adapters/sector-etfs";
import { getVixData } from "@/lib/dashboard/adapters/vix";
import { getVixTermStructureData } from "@/lib/dashboard/adapters/vix-term-structure";
import { buildRegimeSummary } from "@/lib/dashboard/regime-scoring";
import type { DashboardData } from "@/lib/dashboard/types";

export const getDashboardData = cache(async (): Promise<DashboardData> => {
  const [sectorEtfs, btcEtfFlows, vixData, vixTermStructure, gldFlowPressure] = await Promise.all([
    getSectorEtfsData(),
    getBtcEtfFlowsData(),
    getVixData(),
    getVixTermStructureData(),
    getGldFlowPressure(),
  ]);
  const regimeSummary = buildRegimeSummary({
    btcEtfFlows,
    sectorRotation: sectorEtfs.rotation,
    vix: vixData,
  });

  return {
    dashboardModules: [
      sectorEtfs.module,
      vixData.module,
      btcEtfFlows.module,
    ],
    crossSignalRadar: getRadarRows(),
    regimeSummary,
    sectorModule: sectorEtfs.module,
    sectorRotation: sectorEtfs.rotation,
    quantRisk: sectorEtfs.quantRisk,
    vix: vixData,
    vixTermStructure,
    btcEtfFlows,
    ethEtfFlows: null,
    gldFlowPressure,
  };
});

lib/dashboard/adapters/sector-etfs.ts:
import { unstable_cache } from "next/cache.js";
import {
  buildSectorResult,
  buildUnavailableSectorResult,
  MIN_SECTOR_HISTORY,
  parseAlphaVantagePrices,
  sanitizeProviderMessage,
  SECTOR_ETFS,
  type AlphaVantageDailyResponse,
  type SectorEtfsResult,
  type SectorHistory,
} from "./sector-data-core.ts";

const REVALIDATE_SECONDS = 60 * 60 * 24;
const ALPHA_VANTAGE_ENDPOINT = "TIME_SERIES_DAILY";
const ALPHA_VANTAGE_OUTPUTSIZE = "compact";
const ALPHA_VANTAGE_REQUEST_DELAY_MS = 1200;
const ALPHA_VANTAGE_TIMEOUT_MS = 8000;

type SectorFetch = (input: string | URL | Request, init?: RequestInit & { next?: { revalidate: number } }) => Promise<Response>;

type SectorLoadOptions = {
  apiKey?: string;
  fetcher?: SectorFetch;
  sleep?: (milliseconds: number) => Promise<void>;
  now?: number;
};

function providerMessage(payload: AlphaVantageDailyResponse) {
  return payload["Error Message"] ?? payload.Information ?? payload.Note;
}

function logSourceIssue(symbol: string, reason: string, details: Record<string, unknown> = {}) {
  console.warn("[dashboard:sector-etfs]", { symbol, reason, ...details });
}

async function fetchSectorHistory(
  symbol: (typeof SECTOR_ETFS)[number]["symbol"],
  apiKey: string,
  fetcher: SectorFetch,
): Promise<SectorHistory> {
  const meta = SECTOR_ETFS.find((etf) => etf.symbol === symbol);
  if (!meta) throw new Error(`unknown sector symbol: ${symbol}`);

  const url = new URL("https://www.alphavantage.co/query");
  url.searchParams.set("function", ALPHA_VANTAGE_ENDPOINT);
  url.searchParams.set("symbol", symbol);
  url.searchParams.set("outputsize", ALPHA_VANTAGE_OUTPUTSIZE);
  url.searchParams.set("apikey", apiKey);

  const response = await fetcher(url, {
    next: { revalidate: REVALIDATE_SECONDS },
    signal: AbortSignal.timeout(ALPHA_VANTAGE_TIMEOUT_MS),
  });
  if (!response.ok) {
    logSourceIssue(symbol, "http_error", { status: response.status });
    throw new Error(`Alpha Vantage ${symbol} HTTP ${response.status}`);
  }

  const payload = (await response.json()) as AlphaVantageDailyResponse;
  const prices = parseAlphaVantagePrices(payload);
  const message = sanitizeProviderMessage(providerMessage(payload));
  if (message || prices.length < MIN_SECTOR_HISTORY) {
    logSourceIssue(symbol, message ? "provider_message" : "insufficient_history", {
      parsedRows: prices.length,
      message,
      topLevelKeys: Object.keys(payload).slice(0, 8),
    });
    throw new Error(message ? `Alpha Vantage ${symbol} provider response` : `Alpha Vantage ${symbol} returned ${prices.length} sessions`);
  }

  return {
    symbol,
    name: meta.name,
    group: meta.group,
    latestDate: prices.at(-1)?.date ?? "",
    prices,
    closeConvention: "close",
  };
}

export async function loadSectorEtfsData(options: SectorLoadOptions = {}): Promise<SectorEtfsResult> {
  const apiKey = options.apiKey ?? process.env.ALPHA_VANTAGE_API_KEY;
  if (!apiKey) return buildUnavailableSectorResult("credencial de proveedor ausente");

  const fetcher = options.fetcher ?? fetch;
  const sleep = options.sleep ?? ((milliseconds: number) => new Promise((resolve) => setTimeout(resolve, milliseconds)));

  try {
    const histories: SectorHistory[] = [];
    for (const etf of SECTOR_ETFS) {
      histories.push(await fetchSectorHistory(etf.symbol, apiKey, fetcher));
      if (histories.length < SECTOR_ETFS.length) await sleep(ALPHA_VANTAGE_REQUEST_DELAY_MS);
    }
    return buildSectorResult(histories, options.now ?? Date.now());
  } catch (error) {
    const reason = error instanceof Error ? error.message : "error desconocido de fuente";
    return buildUnavailableSectorResult(reason);
  }
}

export function createDailySectorCache(loader: () => Promise<SectorEtfsResult>, now: () => number = Date.now) {
  let cached: { expiresAt: number; promise: Promise<SectorEtfsResult> } | null = null;
  return () => {
    const current = now();
    if (cached && current < cached.expiresAt) return cached.promise;
    cached = { expiresAt: current + REVALIDATE_SECONDS * 1000, promise: loader() };
    return cached.promise;
  };
}

const getPersistentSectorSnapshot = unstable_cache(
  () => loadSectorEtfsData(),
  ["dashboard-sector-snapshot-v2"],
  { revalidate: REVALIDATE_SECONDS, tags: ["dashboard-sector-snapshot"] },
);

const getDailySectorSnapshot = createDailySectorCache(getPersistentSectorSnapshot);

export async function getSectorEtfsData(options?: SectorLoadOptions) {
  return options ? loadSectorEtfsData(options) : getDailySectorSnapshot();
}

export type { SectorEtfsResult } from "./sector-data-core.ts";

import { buildQuantRiskData, buildUnavailableQuantRiskData } from "../risk-models.ts";
import type {
  DashboardModuleData,
  QuantRiskData,
  SectorDetailSeries,
  SectorEtfSnapshot,
  SectorLeadership,
  SectorRotationData,
  SectorRotationMetrics,
} from "../types.ts";

export const SECTOR_ETFS = [
  { symbol: "XLK", name: "Tecnología", group: "growth" },
  { symbol: "XLF", name: "Financieras", group: "cyclical" },
  { symbol: "XLV", name: "Salud", group: "defensive" },
  { symbol: "XLE", name: "Energía", group: "cyclical" },
  { symbol: "XLY", name: "Consumo discrecional", group: "growth" },
  { symbol: "XLP", name: "Consumo básico/defensivo", group: "defensive" },
  { symbol: "XLI", name: "Industriales", group: "cyclical" },
  { symbol: "XLB", name: "Materiales", group: "cyclical" },
  { symbol: "XLU", name: "Utilities", group: "defensive" },
  { symbol: "XLRE", name: "Real Estate", group: "defensive" },
  { symbol: "XLC", name: "Comunicación", group: "growth" },
] as const;

export const SECTOR_SOURCE_NAME = "Alpha Vantage: precios diarios de ETFs sectoriales";
export const SECTOR_SOURCE_URL = "https://www.alphavantage.co/documentation/";
export const SECTOR_UPDATE_FREQUENCY = "Automática server-side con caché diaria; revisión periódica sugerida";
export const MIN_SECTOR_HISTORY = 64;
export const SECTOR_STALE_AFTER_MS = 7 * 24 * 60 * 60 * 1000;

type SectorGroup = (typeof SECTOR_ETFS)[number]["group"];

export type AlphaVantageDailyResponse = {
  "Time Series (Daily)"?: Record<string, { "4. close"?: string; "5. adjusted close"?: string }>;
  "Error Message"?: string;
  Note?: string;
  Information?: string;
};

export type SectorPricePoint = {
  date: string;
  close: number;
};

export type SectorHistory = {
  symbol: string;
  name: string;
  group: SectorGroup;
  latestDate: string;
  prices: SectorPricePoint[];
  closeConvention: "close";
};

export type SectorEtfsResult = {
  module: DashboardModuleData;
  rotation: SectorRotationData | null;
  quantRisk: QuantRiskData;
};

function isIsoDate(value: string) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  return new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value;
}

export function sanitizeProviderMessage(value: string | undefined) {
  if (!value) return undefined;
  return value
    .replace(/API key as\s+[A-Z0-9_-]+/gi, "API key as [redacted]")
    .replace(/apikey[=:]\s*[A-Z0-9_-]+/gi, "apikey=[redacted]");
}

export function parseAlphaVantagePrices(payload: AlphaVantageDailyResponse) {
  const rows = new Map<string, SectorPricePoint>();
  const series = payload["Time Series (Daily)"];

  for (const [date, values] of Object.entries(series ?? {})) {
    const close = Number(values["5. adjusted close"] ?? values["4. close"]);
    if (!isIsoDate(date) || !Number.isFinite(close) || close <= 0) continue;
    rows.set(date, { date, close });
  }

  return [...rows.values()].sort((a, b) => a.date.localeCompare(b.date));
}

function calculateReturn(latest: number, previous: number) {
  return ((latest / previous) - 1) * 100;
}

function calculateDailyReturns(pricesAscending: SectorPricePoint[]) {
  const returns: number[] = [];
  for (let index = 1; index < pricesAscending.length; index += 1) {
    returns.push((pricesAscending[index].close / pricesAscending[index - 1].close) - 1);
  }
  return returns;
}

function rankBy(
  sectors: SectorEtfSnapshot[],
  key: "return1w" | "return1m" | "return3m" | "previousReturn1w" | "previousReturn1m" | "previousReturn3m",
) {
  return [...sectors]
    .filter((sector) => sector[key] !== null)
    .sort((a, b) => (b[key] ?? Number.NEGATIVE_INFINITY) - (a[key] ?? Number.NEGATIVE_INFINITY))
    .map((sector, index) => ({ ticker: sector.etfTicker, rank: index + 1 }));
}

export function applySectorRanks(sectors: SectorEtfSnapshot[]) {
  const rank1w = rankBy(sectors, "return1w");
  const rank1m = rankBy(sectors, "return1m");
  const rank3m = rankBy(sectors, "return3m");
  const previousRank1w = rankBy(sectors, "previousReturn1w");
  const previousRank1m = rankBy(sectors, "previousReturn1m");
  const previousRank3m = rankBy(sectors, "previousReturn3m");

  return sectors.map((sector) => ({
    ...sector,
    rank1w: rank1w.find((rank) => rank.ticker === sector.etfTicker)?.rank ?? sector.rank1w,
    rank1m: rank1m.find((rank) => rank.ticker === sector.etfTicker)?.rank ?? sector.rank1m,
    rank3m: rank3m.find((rank) => rank.ticker === sector.etfTicker)?.rank ?? null,
    previousRank1w: previousRank1w.find((rank) => rank.ticker === sector.etfTicker)?.rank ?? null,
    previousRank1m: previousRank1m.find((rank) => rank.ticker === sector.etfTicker)?.rank ?? null,
    previousRank3m: previousRank3m.find((rank) => rank.ticker === sector.etfTicker)?.rank ?? null,
  }));
}

function averageGroupReturn(sectors: SectorEtfSnapshot[], group: SectorGroup) {
  const values = sectors.filter((sector) => sector.group === group).map((sector) => sector.return1m);
  return values.reduce((sum, value) => sum + value, 0) / values.length;
}

export function buildSectorMetrics(sectors: SectorEtfSnapshot[]): SectorRotationMetrics {
  const returns1w = sectors.map((sector) => sector.return1w);
  const returns1m = sectors.map((sector) => sector.return1m);
  const defensiveLeadership = averageGroupReturn(sectors, "defensive");
  const growthLeadership = averageGroupReturn(sectors, "growth");
  const cyclicalLeadership = averageGroupReturn(sectors, "cyclical");
  const leaders = [
    { label: "defensiva" as SectorLeadership, value: defensiveLeadership },
    { label: "growth" as SectorLeadership, value: growthLeadership },
    { label: "cíclica" as SectorLeadership, value: cyclicalLeadership },
  ].sort((a, b) => b.value - a.value);
  const reading = leaders[0].value - leaders[1].value >= 1 ? leaders[0].label : "mixta";

  return {
    sectorDispersion1w: Math.max(...returns1w) - Math.min(...returns1w),
    sectorDispersion1m: Math.max(...returns1m) - Math.min(...returns1m),
    defensiveLeadership,
    growthLeadership,
    cyclicalLeadership,
    reading,
    interpretation: `La lectura sugiere una rotación ${reading}. No implica dirección futura del mercado.`,
  };
}

function trendFromSparkline(values: number[]) {
  if (values.length < 10) return "flat" as const;
  const start = values.slice(0, 5).reduce((sum, value) => sum + value, 0) / 5;
  const end = values.slice(-5).reduce((sum, value) => sum + value, 0) / 5;
  const change = ((end / start) - 1) * 100;
  if (change > 1) return "up" as const;
  if (change < -1) return "down" as const;
  return "flat" as const;
}

function buildDetailSeries(pricesAscending: number[]): SectorDetailSeries[] {
  return [
    { period: "30d" as const, sessions: 30, label: "Retorno acumulado · 30 sesiones" },
    { period: "63d" as const, sessions: 63, label: "Retorno acumulado · 3 meses aprox." },
    { period: "252d" as const, sessions: 252, label: "Retorno acumulado · 12 meses aprox." },
  ].map(({ label, period, sessions }) => {
    const points = pricesAscending.slice(-sessions);
    return {
      period,
      points,
      label: points.length >= sessions ? label : `Historial disponible · ${points.length} sesiones`,
      availableSessions: points.length,
    };
  });
}

export function buildSectorSnapshot(history: SectorHistory): SectorEtfSnapshot {
  const latestIndex = history.prices.length - 1;
  const latest = history.prices[latestIndex];
  const pricesAscending = history.prices;
  const sparkline30d = history.prices.slice(-30).map((point) => point.close);

  return {
    sectorName: history.name,
    etfTicker: history.symbol,
    latestClose: latest.close,
    return1w: calculateReturn(latest.close, history.prices[latestIndex - 5].close),
    return1m: calculateReturn(latest.close, history.prices[latestIndex - 21].close),
    return3m: history.prices[latestIndex - 63] ? calculateReturn(latest.close, history.prices[latestIndex - 63].close) : null,
    previousReturn1w: history.prices[latestIndex - 10] ? calculateReturn(history.prices[latestIndex - 5].close, history.prices[latestIndex - 10].close) : null,
    previousReturn1m: history.prices[latestIndex - 42] ? calculateReturn(history.prices[latestIndex - 21].close, history.prices[latestIndex - 42].close) : null,
    previousReturn3m: history.prices[latestIndex - 126] ? calculateReturn(history.prices[latestIndex - 63].close, history.prices[latestIndex - 126].close) : null,
    rank1w: 0,
    rank1m: 0,
    rank3m: null,
    previousRank1w: null,
    previousRank1m: null,
    previousRank3m: null,
    sparkline30d,
    detailSeries: buildDetailSeries(pricesAscending.map((point) => point.close)),
    trend: trendFromSparkline(sparkline30d),
    lastUpdated: latest.date,
    group: history.group,
    dailyReturns: calculateDailyReturns(pricesAscending),
  };
}

export function alignSectorHistories(histories: SectorHistory[]) {
  if (histories.length !== SECTOR_ETFS.length) throw new Error(`sector coverage ${histories.length}/${SECTOR_ETFS.length}`);
  const commonDates = histories
    .map((history) => new Set(history.prices.map((point) => point.date)))
    .reduce((common, dates) => new Set([...common].filter((date) => dates.has(date))));
  const orderedCommonDates = [...commonDates].sort((a, b) => a.localeCompare(b));
  if (orderedCommonDates.length < MIN_SECTOR_HISTORY) throw new Error(`common sector history ${orderedCommonDates.length}/${MIN_SECTOR_HISTORY}`);
  const allowed = new Set(orderedCommonDates);
  return histories.map((history) => {
    const prices = history.prices.filter((point) => allowed.has(point.date));
    return { ...history, latestDate: prices.at(-1)?.date ?? history.latestDate, prices };
  });
}

function formatPercent(value: number | null) {
  if (value === null) return "Pendiente de datos suficientes";
  return `${value > 0 ? "+" : ""}${value.toFixed(1)}%`;
}

export function buildSectorResult(histories: SectorHistory[], now = Date.now()): SectorEtfsResult {
  const aligned = alignSectorHistories(histories);
  const latestCommonSession = aligned[0].prices.at(-1)?.date;
  if (!latestCommonSession) throw new Error("latest common sector session is unavailable");
  const age = now - new Date(`${latestCommonSession}T23:59:59Z`).getTime();
  if (age > SECTOR_STALE_AFTER_MS) throw new Error(`latest common sector session is stale: ${latestCommonSession}`);

  const sectors = applySectorRanks(aligned.map(buildSectorSnapshot));
  const metrics = buildSectorMetrics(sectors);
  const byWeek = [...sectors].sort((a, b) => b.return1w - a.return1w);
  const byMonth = [...sectors].sort((a, b) => b.return1m - a.return1m);
  const byQuarter = [...sectors].sort((a, b) => (b.return3m ?? Number.NEGATIVE_INFINITY) - (a.return3m ?? Number.NEGATIVE_INFINITY));
  const lastUpdated = `Automático con fuente pública: ${latestCommonSession}`;
  const rotation: SectorRotationData = {
    sourceName: SECTOR_SOURCE_NAME,
    sourceUrl: SECTOR_SOURCE_URL,
    lastUpdated,
    updateFrequency: SECTOR_UPDATE_FREQUENCY,
    dataStatus: "automated",
    reliabilityNote: "La rotación se estima mediante ETFs sectoriales líquidos como proxies. Puede diferir de índices o grupos sectoriales de otros proveedores.",
    sectors,
    metrics,
    closeConvention: "close",
  };

  return {
    module: {
      id: "sectors",
      title: "Rotación sectorial por ETFs",
      status: metrics.reading === "mixta" ? "Lectura mixta" : `Lectura ${metrics.reading}`,
      sourceName: rotation.sourceName,
      sourceUrl: rotation.sourceUrl,
      lastUpdated,
      updateFrequency: rotation.updateFrequency,
      dataStatus: "automated",
      reliabilityNote: `${rotation.reliabilityNote} Convención usada: cierre diario; 1W = 5 sesiones, 1M = 21 sesiones, 3M = 63 sesiones.`,
      observedData: [
        ["Universo proxy", SECTOR_ETFS.map((etf) => `${etf.symbol} ${etf.name}`).join(", ")],
        ["Top 1W", byWeek.slice(0, 3).map((sector) => `${sector.etfTicker} ${formatPercent(sector.return1w)}`).join(", ")],
        ["Bottom 1W", byWeek.slice(-3).reverse().map((sector) => `${sector.etfTicker} ${formatPercent(sector.return1w)}`).join(", ")],
        ["Top 1M", byMonth.slice(0, 3).map((sector) => `${sector.etfTicker} ${formatPercent(sector.return1m)}`).join(", ")],
        ["Top 3M", byQuarter.slice(0, 3).map((sector) => `${sector.etfTicker} ${formatPercent(sector.return3m)}`).join(", ")],
        ["Lectura", metrics.interpretation],
      ],
      interpretation: {
        lookingAt: "Performance de ETFs sectoriales con retornos por sesiones de mercado: 5, 21 y 63 sesiones.",
        why: "Ayuda a observar si la presión relativa se concentra en sectores defensivos, cíclicos o growth.",
        how: "La rotación apunta a una lectura prudente de liderazgo relativo; diferencias pequeñas deben tratarse como mixtas.",
        whatItDoesNotMean: "No implica dirección futura del mercado, no muestra acciones individuales y no es una lectura personalizada.",
      },
    },
    rotation,
    quantRisk: buildQuantRiskData(sectors, metrics, lastUpdated),
  };
}

export function buildUnavailableSectorResult(reason: string): SectorEtfsResult {
  const lastUpdated = "Fuente temporalmente no disponible";
  const reliabilityNote = "Alpha Vantage no devolvió un snapshot completo y válido para los 11 ETFs sectoriales. No se sustituyen rankings, barras ni cálculos con historiales sintéticos.";
  return {
    module: {
      id: "sectors",
      title: "Rotación sectorial por ETFs",
      status: "Datos temporalmente no disponibles",
      sourceName: SECTOR_SOURCE_NAME,
      sourceUrl: SECTOR_SOURCE_URL,
      lastUpdated,
      updateFrequency: SECTOR_UPDATE_FREQUENCY,
      dataStatus: "unavailable",
      reliabilityNote,
      observedData: [],
      interpretation: {
        lookingAt: "La rotación sectorial queda pendiente hasta disponer de un snapshot real y completo.",
        why: "Un universo incompleto no permite comparar liderazgo y rezago con la cobertura gobernada.",
        how: "La lectura se reanuda cuando los 11 ETFs superan validación de fechas, cierres e historial.",
        whatItDoesNotMean: "La ausencia temporal del dato no implica una rotación neutral ni defensiva.",
      },
    },
    rotation: null,
    quantRisk: buildUnavailableQuantRiskData(reason),
  };
}

lib/dashboard/adapters/vix.ts:
import type { DashboardModuleData, LegacyVixTermStructureData, VixDashboardData, VixHistoryPoint, VixSpotData } from "@/lib/dashboard/types";

type VixFetch = (input: string | URL | Request, init?: RequestInit) => Promise<Response>;
type GetVixDataOptions = { fetcher?: VixFetch };

const FRED_VIX_SOURCE_URL = "https://fred.stlouisfed.org/series/VIXCLS";
const FRED_VIX_CSV_URL = "https://fred.stlouisfed.org/graph/fredgraph.csv?id=VIXCLS";
const FRED_TIMEOUT_MS = 8000;
const MIN_ANALYTICAL_HISTORY = 6;
const RECENT_SESSION_COUNT = 24;

function logVixSourceIssue(reason: string, details: Record<string, unknown> = {}) {
  console.warn("[dashboard:vix]", { reason, ...details });
}

function parseVixValue(value: string) {
  if (!value || value === ".") return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed >= 0 ? parsed : null;
}

function isValidObservationDate(value: string) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const date = new Date(`${value}T00:00:00Z`);
  return !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === value;
}

export function normalizeVixHistory(points: VixHistoryPoint[]) {
  const byDate = new Map<string, VixHistoryPoint>();
  for (const point of points) {
    if (!isValidObservationDate(point.date) || !Number.isFinite(point.value) || point.value < 0) continue;
    byDate.set(point.date, { date: point.date, value: point.value });
  }
  return [...byDate.values()].sort((a, b) => a.date.localeCompare(b.date));
}

export function parseFredCsv(csv: string): VixHistoryPoint[] {
  const rows = csv.replace(/^\uFEFF/, "").trim().split(/\r?\n/);
  if (rows.length < 2) return [];
  return normalizeVixHistory(rows.slice(1).flatMap((line) => {
    const separator = line.indexOf(",");
    if (separator < 0) return [];
    const date = line.slice(0, separator).trim();
    const value = parseVixValue(line.slice(separator + 1).trim());
    return value === null ? [] : [{ date, value }];
  }));
}

async function fetchFredPublicCsv(fetcher: VixFetch): Promise<VixHistoryPoint[]> {
  const response = await fetcher(FRED_VIX_CSV_URL, { next: { revalidate: 86400 }, signal: AbortSignal.timeout(FRED_TIMEOUT_MS) });
  const text = await response.text();
  if (!response.ok) {
    logVixSourceIssue("fred_csv_error", { source: "FRED public CSV VIXCLS", status: response.status });
    return [];
  }
  return parseFredCsv(text);
}

export async function fetchVixHistory({ fetcher = fetch }: GetVixDataOptions = {}) {
  try {
    return await fetchFredPublicCsv(fetcher);
  } catch (error) {
    logVixSourceIssue("fred_csv_request_failed", { message: error instanceof Error ? error.message : "Unknown error" });
    return [];
  }
}

export function formatVixObservationDate(date: string) {
  return new Intl.DateTimeFormat("es-CO", { day: "2-digit", month: "short", year: "numeric", timeZone: "UTC" }).format(new Date(`${date}T00:00:00Z`));
}

function formatVix(value: number | null) {
  return value === null ? "Dato no disponible temporalmente" : value.toFixed(1);
}

function formatChange(value: number | null) {
  if (value === null) return "Historial insuficiente";
  return `${value > 0 ? "+" : ""}${value.toFixed(1)} pts`;
}

function vixLevelFor(latestVix: number): Pick<VixSpotData, "vixLevelLabel" | "vixSeverity" | "vixDescription"> {
  if (latestVix >= 40) return { vixLevelLabel: "Estrés extremo", vixSeverity: "extreme", vixDescription: "Lectura excepcionalmente elevada de volatilidad implícita." };
  if (latestVix >= 30) return { vixLevelLabel: "Estrés", vixSeverity: "stress", vixDescription: "Volatilidad implícita alta, normalmente asociada a mayor demanda de protección." };
  if (latestVix >= 25) return { vixLevelLabel: "Tensión", vixSeverity: "elevated", vixDescription: "Presión de volatilidad elevada frente a condiciones normales." };
  if (latestVix >= 20) return { vixLevelLabel: "Vigilancia", vixSeverity: "watch", vixDescription: "La volatilidad entra en una zona donde suele aumentar la sensibilidad del mercado." };
  if (latestVix >= 16) return { vixLevelLabel: "Normal alto", vixSeverity: "watch", vixDescription: "Volatilidad todavía moderada, pero acercándose a zona de vigilancia." };
  if (latestVix >= 12) return { vixLevelLabel: "Normal bajo", vixSeverity: "normal", vixDescription: "Entorno de volatilidad contenido." };
  return { vixLevelLabel: "Complacencia", vixSeverity: "low", vixDescription: "Volatilidad implícita muy baja frente a rangos habituales." };
}

function relativeChange(current: number, previous: number | null | undefined) {
  return !previous || previous <= 0 ? null : ((current - previous) / previous) * 100;
}

function vixTrendFor(change1dPct: number | null, change5dPct: number | null): VixSpotData["vixTrend"] {
  if (change5dPct === null && change1dPct === null) return "stable";
  if ((change5dPct ?? -Infinity) >= 15 || (change1dPct ?? -Infinity) >= 8) return "rising_fast";
  if ((change5dPct ?? -Infinity) >= 5) return "rising";
  if ((change5dPct ?? Infinity) <= -10) return "falling";
  return "stable";
}

function percentileFor(history: VixHistoryPoint[], latestVix: number) {
  return history.length < 252 ? null : (history.filter((point) => point.value <= latestVix).length / history.length) * 100;
}

function percentileLabelFor(percentile: number | null) {
  if (percentile === null) return "Historial insuficiente";
  if (percentile >= 95) return "Extremo frente a su historia";
  if (percentile >= 80) return "Alto frente a su historia";
  if (percentile >= 60) return "Por encima de lo habitual";
  if (percentile >= 25) return "En rango habitual";
  return "Bajo frente a su historia reciente";
}

function compositeReadingFor(latestVix: number, level: Pick<VixSpotData, "vixLevelLabel" | "vixSeverity">, percentile: number | null, trend: VixSpotData["vixTrend"]): Pick<VixSpotData, "vixCompositeLabel" | "vixCompositeSubtext" | "vixSeverity"> {
  if (latestVix >= 40) return { vixCompositeLabel: "Estrés extremo", vixCompositeSubtext: "Lectura excepcional de presión de volatilidad.", vixSeverity: "extreme" };
  if (latestVix >= 30) return { vixCompositeLabel: "Estrés", vixCompositeSubtext: "Mayor demanda implícita de protección.", vixSeverity: "stress" };
  if (latestVix >= 25) return { vixCompositeLabel: "Tensión", vixCompositeSubtext: "Estrés de mercado por encima de rangos normales.", vixSeverity: "elevated" };
  if (latestVix >= 20) return { vixCompositeLabel: "Vigilancia", vixCompositeSubtext: trend === "rising" || trend === "rising_fast" ? "Presión de volatilidad en aumento." : "Volatilidad en zona de mayor sensibilidad.", vixSeverity: "watch" };
  if (latestVix >= 18 && (trend === "rising" || trend === "rising_fast" || (percentile ?? 0) > 60)) return { vixCompositeLabel: "Vigilancia", vixCompositeSubtext: "Volatilidad acercándose a zona de tensión.", vixSeverity: "watch" };
  if (latestVix >= 18) return { vixCompositeLabel: "Normal alto", vixCompositeSubtext: "Cerca de zona de vigilancia.", vixSeverity: "watch" };
  return { vixCompositeLabel: level.vixLevelLabel, vixCompositeSubtext: level.vixSeverity === "low" ? "Volatilidad implícita muy contenida." : "Presión de volatilidad contenida.", vixSeverity: level.vixSeverity };
}

function buildTermStructureFallback(latestVix: number | null, lastUpdated: string): LegacyVixTermStructureData {
  return {
    sourceName: "CBOE / VIX futures term structure", sourceUrl: "https://www.cboe.com/tradable_products/vix/", lastUpdated,
    updateFrequency: "Pendiente de proveedor estable", dataStatus: "live_pending",
    reliabilityNote: "Estructura preparada para VIX futures cercanos. No se automatiza hasta validar permisos, proveedor y timestamp sin scraping frágil.",
    spot: latestVix, futureMonth1: null, futureMonth2: null, spreadM2M1: null, curveState: "live_pending",
    interpretation: {
      lookingAt: "Relación entre VIX spot y futuros cercanos para observar si se paga más por protección cercana o futura.",
      why: "Ayuda a diferenciar tensión inmediata de una curva más normalizada.", how: "Contango suele asociarse con menor tensión inmediata; backwardation suele indicar más estrés cercano.",
      whatItDoesNotMean: "No anticipa por sí sola la dirección del mercado ni marca puntos de entrada o salida.",
    },
  };
}

function buildModule(spot: VixSpotData): DashboardModuleData {
  return {
    id: "vix", title: "VIX / volatilidad",
    status: spot.dataStatus === "automated" ? "Datos automatizados" : spot.latestVix === null ? "Datos temporalmente no disponibles" : "Datos con retraso",
    sourceName: spot.sourceName, sourceUrl: spot.sourceUrl, lastUpdated: spot.lastUpdated, updateFrequency: spot.updateFrequency,
    dataStatus: spot.dataStatus, reliabilityNote: spot.reliabilityNote,
    observedData: [["VIX último cierre", formatVix(spot.latestVix)], ["Cambio 1D", formatChange(spot.change1d)], ["Cambio 5D", formatChange(spot.change5d)], ["Cambio 21D", formatChange(spot.change21d)], ["Lectura", spot.vixCompositeLabel]],
    interpretation: spot.interpretation,
  };
}

function unavailableVixData(): VixDashboardData {
  const lastUpdated = "Sin observación válida disponible";
  const spot: VixSpotData = {
    sourceName: "FRED VIXCLS", sourceUrl: FRED_VIX_SOURCE_URL, lastUpdated, updateFrequency: "Diaria · último cierre disponible", dataStatus: "unavailable",
    reliabilityNote: "La fuente oficial no devolvió un historial válido. No se sustituyen valores, métricas ni gráficos con datos fabricados.",
    lastObservationDate: null, latestVix: null, previousVix: null, change1d: null, change5d: null, change21d: null, vixPercentile: null,
    vixLevelLabel: "No disponible", vixSeverity: "normal", vixDescription: "Datos temporalmente no disponibles.",
    vixCompositeLabel: "No disponible", vixCompositeSubtext: "Datos temporalmente no disponibles. La lectura se reanudará cuando FRED publique un historial válido.",
    vixPercentileLabel: "No disponible", vixTrend: "stable", history: [],
    interpretation: {
      lookingAt: "Último cierre disponible del VIX y cambios recientes de volatilidad implícita del S&P 500.", why: "El VIX resume expectativas de volatilidad implícita y ayuda a leer presión de riesgo.",
      how: "La lectura permanece no disponible mientras no exista un historial oficial válido.", whatItDoesNotMean: "La ausencia temporal del dato no permite inferir un nivel, tendencia o dirección de mercado.",
    },
  };
  return { spot, termStructure: buildTermStructureFallback(null, lastUpdated), module: buildModule(spot) };
}

export function buildVixDashboardData(rawHistory: VixHistoryPoint[]): VixDashboardData {
  const history = normalizeVixHistory(rawHistory);
  if (history.length < MIN_ANALYTICAL_HISTORY) return unavailableVixData();
  const latest = history.at(-1);
  const previous = history.at(-2);
  if (!latest || !previous) return unavailableVixData();
  const percentile = percentileFor(history, latest.value);
  const level = vixLevelFor(latest.value);
  const trend = vixTrendFor(relativeChange(latest.value, previous.value), relativeChange(latest.value, history.at(-6)?.value));
  const composite = compositeReadingFor(latest.value, level, percentile, trend);
  const lastUpdated = `Último cierre disponible: ${formatVixObservationDate(latest.date)}`;
  const spot: VixSpotData = {
    sourceName: "FRED VIXCLS", sourceUrl: FRED_VIX_SOURCE_URL, lastUpdated, updateFrequency: "Diaria · último cierre disponible", dataStatus: "automated",
    reliabilityNote: "Dato diario de cierre publicado por FRED. Puede tener retraso, revisiones o días sin observación; no representa cotización intradía.",
    lastObservationDate: latest.date, latestVix: latest.value, previousVix: previous.value, change1d: latest.value - previous.value,
    change5d: latest.value - history[history.length - 6].value, change21d: history.length >= 22 ? latest.value - history[history.length - 22].value : null,
    vixPercentile: percentile, vixLevelLabel: level.vixLevelLabel, vixSeverity: composite.vixSeverity, vixDescription: level.vixDescription,
    vixCompositeLabel: composite.vixCompositeLabel, vixCompositeSubtext: composite.vixCompositeSubtext, vixPercentileLabel: percentileLabelFor(percentile), vixTrend: trend,
    history: history.slice(-RECENT_SESSION_COUNT),
    interpretation: {
      lookingAt: "Último cierre disponible del VIX y cambios recientes de volatilidad implícita del S&P 500.",
      why: "El VIX resume expectativas de volatilidad implícita del S&P 500 a partir de opciones. Es una lectura de presión de riesgo, no una lectura de dirección del mercado.",
      how: "Lectura compuesta basada en nivel absoluto, percentil histórico y momentum reciente. Niveles más altos suelen sugerir más tensión de volatilidad.",
      whatItDoesNotMean: "Un VIX alto no significa automáticamente caída futura del mercado. Un VIX bajo tampoco elimina el riesgo. Mide expectativas implícitas de volatilidad, no dirección ni retorno esperado.",
    },
  };
  return { spot, termStructure: buildTermStructureFallback(latest.value, lastUpdated), module: buildModule(spot) };
}

export async function getVixData(options: GetVixDataOptions = {}): Promise<VixDashboardData> {
  const history = await fetchVixHistory(options);
  if (history.length < MIN_ANALYTICAL_HISTORY) logVixSourceIssue("insufficient_valid_vix_history", { source: "FRED VIXCLS", validObservations: history.length });
  return buildVixDashboardData(history);
}

